type Renderer = { render(page: string): string };

const renderers: Record<string, () => Promise<{ default: Renderer }>> = {
  html: () => import("./renderers/html.js"),
  pdf:  () => import("./renderers/pdf.js"),
};

export async function lookup(name: string): Promise<Renderer> {
  const load = renderers[name];
  if (!load) throw new Error(`unknown renderer: ${name}`);   // fail fast, typed
  return (await load()).default;
}
